-- Clues are now generated by the game from fixed, visible desk decorations.
-- No manual authorship or daily scene publication is required.
-- This procedure only records each recipient's opt-in reveal step.
create or replace function public.ss_unlock_hint(
  p_event_id uuid,p_child_id uuid
) returns integer
language plpgsql security invoker set search_path=''
as $function$
declare
  v_assignment public.ss_assignments%rowtype;
  v_next integer;
begin
  select * into v_assignment
    from public.ss_assignments
    where event_id=p_event_id and child_id=p_child_id
    for update;
  if not found then
    raise exception 'Your Santa assignment has not been drawn';
  end if;
  v_next:=v_assignment.hints_unlocked_count+1;
  if v_next>3 then
    raise exception 'All three office clues are already unlocked';
  end if;
  if v_assignment.hint_last_unlocked_at is not null
     and now()<v_assignment.hint_last_unlocked_at+interval '24 hours' then
    raise exception 'Your next office clue unlocks 24 hours after the previous one';
  end if;
  update public.ss_assignments
     set hints_unlocked_count=v_next,
         hint_last_unlocked_at=now(),updated_at=now()
    where id=v_assignment.id;
  return v_next;
end;
$function$;

-- Deprecate manually authored Santa hints; any previously written texts are
-- preserved in the database for audit but never sent to a player's client.
revoke all on function public.ss_save_santa_hints(uuid,uuid,jsonb)
  from public,anon,authenticated,service_role;
revoke all on function public.ss_unlock_hint(uuid,uuid)
  from public,anon,authenticated;
grant execute on function public.ss_unlock_hint(uuid,uuid) to service_role;
